for _ in range(int(input())):
	n = int(input())
	if n != 2:
		print('YES')
		if n == 1:
			print(1)
		else:
			a = [i for i in range(n, n // 2 + n % 2, -1)] + [i for i in range(1, (n + 1) // 2 + 1)]
			if n % 2 == 0:
				(a[0], a[1]) = (a[1], a[0])
			print(*a)
	else:
		print('NO')
